from typing import List, Any
import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import filter_integers


def ref_filter(values: List[Any]) -> List[int]:
    # Obviously-correct reference: only values whose exact type is int.
    # bool has type bool, not int, so True/False must be excluded even
    # though isinstance(True, int) is True.
    return [v for v in values if type(v) is int]


# ---- explicit examples from spec docstring ----

def test_example_1_mixed_str_float_int():
    assert filter_integers(['a', 3.14, 5]) == [5]


def test_example_2_ints_and_containers():
    assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]


# ---- edge / boundary examples derived from spec ----

def test_empty_list_returns_empty():
    assert filter_integers([]) == []


def test_booleans_are_not_integers_empty():
    # True/False are booleans, not integers, must be filtered out.
    assert filter_integers([True, False]) == []


def test_booleans_are_not_integers_mixed_with_ints():
    assert filter_integers([True, 1, False, 0, 2]) == [1, 0, 2]


def test_boolean_true_not_confused_with_one():
    # Even though True == 1, only exact ints survive.
    result = filter_integers([True])
    assert result == []
    assert result != [1]


def test_boolean_false_not_confused_with_zero():
    result = filter_integers([False])
    assert result == []
    assert result != [0]


def test_integral_floats_excluded():
    assert filter_integers([3.0, 2.0, 1, 0.0]) == [1]


def test_negative_zero_and_large_ints_preserved():
    vals = [-10, 0, 10, 2**62, -(2**100), 2**100]
    assert filter_integers(vals) == vals


def test_all_non_int_types_excluded():
    vals = ['a', '1', 3.14, 3.0, None, {}, [], (), set(), b'x', object()]
    assert filter_integers(vals) == []


def test_only_ints_preserved_in_order():
    vals = [5, 'a', 6, 7.5, 8]
    assert filter_integers(vals) == [5, 6, 8]


# ---- property-based tests ----

mixed_scalar = st.one_of(
    st.integers(min_value=-(2**63) - 100, max_value=2**63 + 100),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False),
    st.text(max_size=5),
    st.none(),
    st.just({}),
    st.just([]),
    st.just(()),
)

@given(st.lists(mixed_scalar, max_size=20))
def test_property_result_matches_exact_int_reference_model(values):
    assert filter_integers(values) == ref_filter(values)


@given(st.lists(mixed_scalar, max_size=20))
def test_property_every_returned_element_has_exact_type_int(values):
    result = filter_integers(values)
    assert type(result) == list
    for x in result:
        assert type(x) is int


@given(st.lists(mixed_scalar, max_size=20))
def test_property_no_booleans_in_result(values):
    result = filter_integers(values)
    for x in result:
        assert not isinstance(x, bool)


@given(st.lists(mixed_scalar, max_size=20))
def test_property_result_is_ordered_subsequence_of_input(values):
    result = filter_integers(values)
    # result must appear in input in same order with equality
    idx = 0
    for v in values:
        if idx < len(result) and v == result[idx] and type(v) is int:
            idx += 1
    assert idx == len(result)
    # length cannot exceed number of exact ints in input
    assert len(result) == len(ref_filter(values))


@given(st.lists(st.integers(), max_size=20))
def test_property_all_int_list_is_identity(values):
    assert filter_integers(values) == values


@given(st.lists(st.one_of(
    st.text(max_size=5),
    st.floats(allow_nan=False, allow_infinity=False),
    st.none(),
    st.booleans(),
    st.lists(st.integers(max_value=10), max_size=3),
    st.dictionaries(st.text(max_size=3), st.integers(max_value=10), max_size=3),
), max_size=20))
def test_property_no_exact_ints_gives_empty(values):
    # strategies above never produce exact ints (booleans excluded),
    # so result must be empty. Filter out any accidental exact int.
    assume_vals = [v for v in values if type(v) is not int]
    assert filter_integers(assume_vals) == []


@given(st.lists(mixed_scalar, max_size=20))
def test_property_filtering_is_idempotent(values):
    once = filter_integers(values)
    twice = filter_integers(once)
    assert twice == once
